import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2021-08-05","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-08-05","date":"2021-08-05T00:00:00.000Z","updated":"2021-08-21T00:00:00.000Z","tags":["Ceph","性能优化","蓝店 (BlueStore)","写放大","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-08-05.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-08-05.md","lastUpdated":1780460162000}'),l={name:"posts/2021/Ceph_Performance_Meeting_2021-08-05.md"};function i(n,e,s,h,u,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>新PR</strong>: 本次会议讨论了一个新的PR，该PR涉及MDS锁的改进，将锁从非公平互斥锁更改为公平互斥锁，旨在改善等待时间较长的请求的处理，避免资源饥饿。</li><li><strong>已关闭PR</strong>: Kifu合并了一个关于PG日志的更改PR，具体是关于回滚信息的修剪。</li><li><strong>更新PR</strong>: 多个PR正在积极审查和开发中，包括RGW跟踪工作、缓冲区列表的PR以及TTL缓存实现的长期工作。</li><li><strong>性能问题</strong>: Red Hat内部工作组在基于Pacific的新存储版本中发现了性能提升，但NVMe基础的DB和WAL分区在OSD中出现了显著的写放大问题，导致SSD驱动器的工作负载比之前版本更重。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>写放大问题</strong>: 讨论了BlueStore中首选延迟大小与Blob大小的关系，以及这对写操作的影响。特别是，当首选延迟大小等于或大于Blob大小时，会导致大量的延迟I/O流量进入RocksDB的写前日志和MemTable缓冲区，从而引发写放大问题。</li><li><strong>代码逻辑和行为</strong>: 讨论了BlueStore处理大写操作的逻辑，以及如何通过调整参数（如首选延迟大小）来优化性能和减少写放大。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>进一步测试和分析</strong>: 决定进行更多测试，特别是简化场景的测试，以更好地理解写放大问题的原因和潜在的解决方案。</li><li><strong>代码审查和优化</strong>: 需要进一步审查和优化BlueStore的代码，特别是在处理大写操作和延迟写入的逻辑上。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>性能测试</strong>: 进行更多性能测试，特别是在不同配置下测试写放大问题。</li><li><strong>代码审查</strong>: 继续审查和优化BlueStore的代码，特别是与写操作和延迟写入相关的部分。</li><li><strong>参数调整</strong>: 考虑调整BlueStore的首选延迟大小参数，以减少写放大并优化性能。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议讨论了Ceph存储系统中关于MDS锁改进和BlueStore中写放大问题等多个开发和性能优化问题。决定进行更多测试和代码审查，以解决这些问题并优化系统性能。</p><h3 id="改进点" tabindex="-1">改进点 <a class="header-anchor" href="#改进点" aria-label="Permalink to &quot;改进点&quot;">​</a></h3><ul><li>增加了关于BlueStore中写放大问题的详细描述。</li><li>优化了关于性能测试和代码审查的行动计划。</li><li>确保保留计算机科学/CEPH相关领域的英文原文关键词。</li></ul>',13)])])}const g=a(l,[["render",i]]);export{_ as __pageData,g as default};
